code_string = """from scipy.optimize import minimize
from qiskit import transpile

def run_and_analyze(circuit, aer_sim, graph):
    initial_value = 0.5
    initial_params = [initial_value] * circuit.num_parameters
    parameters = list(circuit.parameters)
    try:
        parameters = sorted(parameters, key=lambda parameter: parameter.name)
    except Exception:
        parameters = list(circuit.parameters)
    optimized_circuit = transpile(circuit, aer_sim)

    def run_counts(parameter_values, shots=512):
        parameter_binds = [{parameters[index]: [float(parameter_values[index])] for index in range(len(parameters))}]
        job = aer_sim.run(optimized_circuit, shots=shots, parameter_binds=parameter_binds)
        result = job.result()
        return result.get_counts()

    def objective(parameter_values):
        counts = run_counts(parameter_values)
        return -float(compute_expectation(counts, graph))

    best_params = initial_params
    best_value = objective(best_params)
    starts = [
        initial_params,
        [0.8] * circuit.num_parameters,
        [1.2] * circuit.num_parameters,
        [0.35, 0.7, 0.85, 0.45][:circuit.num_parameters],
        [0.65, 0.35, 1.05, 0.75][:circuit.num_parameters]
    ]
    for start in starts:
        if len(start) == circuit.num_parameters:
            try:
                result = minimize(objective, start, method='COBYLA', options={'maxiter': 80, 'rhobeg': 0.8})
                if float(result.fun) < best_value:
                    best_value = float(result.fun)
                    best_params = list(result.x)
            except Exception:
                pass

    final_counts = run_counts(best_params, shots=4096)
    top_two = [item[0] for item in sorted(final_counts.items(), key=lambda item: item[1], reverse=True)[:2]]
    return top_two
"""
